import pathlib,json,datetime
import pandas as pd
R=pathlib.Path(__file__).resolve().parents[1];p=R/'normalized/nbs_national_normalized.parquet';d=pd.read_parquet(p);keys=['frequency','catalog_id','indicator_id','indicator_name','unit'];a=d.groupby(keys,dropna=False).agg(requested_max_period_end=('period_end','max'),observations=('period_end','size')).reset_index();b=d[d.value_numeric.notna()].groupby(keys,dropna=False).agg(latest_nonnull_period_end=('period_end','max'),earliest_nonnull_period_start=('period_start','min'),nonnull_observations=('value_numeric','size')).reset_index();a=a.merge(b,how='left',on=keys);a['publication_date_known']=False;a['expected_latest_publication_verified']=False;a['vintage']='latest revised as retrieved';a['audit_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat();a.to_parquet(R/'logs/nbs-indicator-freshness.parquet',index=False);summary=a.groupby(['frequency','latest_nonnull_period_end'],dropna=False).size().reset_index(name='indicator_count');summary.to_csv(R/'logs/nbs-latest-period-distribution.csv',index=False);print(len(a),len(summary))
